BEGIN;
CREATE SCHEMA IF NOT EXISTS galgo;
-- Run on a Neon preview branch. Lakebase extensions must be available on the target branch.
CREATE EXTENSION IF NOT EXISTS lakebase_vector;
CREATE EXTENSION IF NOT EXISTS lakebase_text;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS ltree;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TYPE galgo.evidence_level AS ENUM ('Confirmed','Probable','Plausible','Disputed','Traditional claim','Unsupported','Disproven or materially misleading');
CREATE TYPE galgo.corpus_status AS ENUM ('canonical','draft','legacy','superseded','methodology');
CREATE TYPE galgo.source_tier AS ENUM ('tier_1','tier_2','tier_3','tier_4');
CREATE TABLE galgo.corpus_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id text UNIQUE,repository_path text NOT NULL UNIQUE,filename text NOT NULL,title text NOT NULL,slug text NOT NULL UNIQUE,batch text,document_type text,language text,source_languages jsonb NOT NULL DEFAULT '[]',period_labels jsonb NOT NULL DEFAULT '[]',period_start_year int,period_end_year int,geographies jsonb NOT NULL DEFAULT '[]',entities jsonb NOT NULL DEFAULT '[]',people jsonb NOT NULL DEFAULT '[]',dog_types jsonb NOT NULL DEFAULT '[]',topics jsonb NOT NULL DEFAULT '[]',evidence_level galgo.evidence_level,source_quality galgo.source_tier,review_status text,corpus_status galgo.corpus_status NOT NULL,git_sha text NOT NULL,content_hash text NOT NULL,frontmatter jsonb NOT NULL DEFAULT '{}',markdown text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),ingested_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE galgo.document_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES galgo.corpus_documents(id),git_sha text NOT NULL,content_hash text NOT NULL,markdown text NOT NULL,frontmatter jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,content_hash));
CREATE TABLE galgo.document_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES galgo.corpus_documents(id) ON DELETE CASCADE,heading text NOT NULL,heading_path ltree,heading_level smallint NOT NULL,line_start int NOT NULL,line_end int NOT NULL,text text NOT NULL);
CREATE TABLE galgo.chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES galgo.corpus_documents(id) ON DELETE CASCADE,section_id uuid REFERENCES galgo.document_sections(id) ON DELETE SET NULL,chunk_index int NOT NULL,heading_path text NOT NULL,line_start int NOT NULL,line_end int NOT NULL,text text NOT NULL,content_hash text NOT NULL,token_count int,embedding vector,searchable tsvector GENERATED ALWAYS AS (to_tsvector('english',text)) STORED,embedding_model text,extraction_version text NOT NULL,UNIQUE(document_id,chunk_index,extraction_version));
CREATE INDEX chunks_text_idx ON galgo.chunks USING GIN(searchable);CREATE INDEX chunks_embedding_idx ON galgo.chunks USING hnsw(embedding vector_cosine_ops);
CREATE TABLE galgo.sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),canonical_key text UNIQUE NOT NULL,raw_citation text NOT NULL,author_editor text,title text,source_type text,publication text,year text,url text,archive_identifier text,locator text,source_tier galgo.source_tier NOT NULL,language text,notes text);
CREATE TABLE galgo.claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_text text NOT NULL,document_id uuid NOT NULL REFERENCES galgo.corpus_documents(id),section_id uuid REFERENCES galgo.document_sections(id),line_start int NOT NULL,line_end int NOT NULL,raw_span text NOT NULL,evidence_level galgo.evidence_level NOT NULL,extraction_confidence numeric(4,3),review_status text NOT NULL DEFAULT 'unreviewed',period_label text,geography text,notes text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE galgo.continuity_dimensions(id smallint PRIMARY KEY,name text UNIQUE NOT NULL CHECK(name IN ('function','morphological type','population','name','formal breed')));INSERT INTO galgo.continuity_dimensions VALUES (1,'function'),(2,'morphological type'),(3,'population'),(4,'name'),(5,'formal breed') ON CONFLICT DO NOTHING;CREATE TABLE galgo.claim_continuity_dimensions(claim_id uuid REFERENCES galgo.claims(id) ON DELETE CASCADE,dimension_id smallint REFERENCES galgo.continuity_dimensions(id),PRIMARY KEY(claim_id,dimension_id));
CREATE TABLE galgo.claim_sources(claim_id uuid REFERENCES galgo.claims(id) ON DELETE CASCADE,source_id uuid REFERENCES galgo.sources(id),relationship text NOT NULL CHECK(relationship IN ('supports','contradicts','qualifies','contextualizes','cited')),PRIMARY KEY(claim_id,source_id));
CREATE TABLE galgo.entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,entity_class text NOT NULL,description text,UNIQUE(name,entity_class));CREATE TABLE galgo.entity_aliases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES galgo.entities(id) ON DELETE CASCADE,alias text NOT NULL,language text,UNIQUE(entity_id,alias));CREATE TABLE galgo.entity_mentions(entity_id uuid REFERENCES galgo.entities(id),document_id uuid REFERENCES galgo.corpus_documents(id),section_id uuid REFERENCES galgo.document_sections(id),line_start int NOT NULL,line_end int NOT NULL,PRIMARY KEY(entity_id,document_id,line_start));
CREATE TABLE galgo.relationships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_entity_id uuid NOT NULL REFERENCES galgo.entities(id),relationship_type text NOT NULL,target_entity_id uuid NOT NULL REFERENCES galgo.entities(id),claim_id uuid REFERENCES galgo.claims(id),evidence_level galgo.evidence_level NOT NULL,provenance text NOT NULL,date_start_year int,date_end_year int,document_id uuid REFERENCES galgo.corpus_documents(id),line_start int,line_end int,confidence numeric(4,3),quantitative_weight numeric,CHECK(source_entity_id<>target_entity_id));
CREATE TABLE galgo.timeline_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,description text,date_start_year int,date_end_year int,date_label text NOT NULL,uncertainty text,event_category text,document_id uuid REFERENCES galgo.corpus_documents(id),claim_id uuid REFERENCES galgo.claims(id),source_id uuid REFERENCES galgo.sources(id));CREATE TABLE galgo.places(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,geometry geography,source_id uuid REFERENCES galgo.sources(id),notes text);CREATE TABLE galgo.media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),creator text,work text,date_label text,institution text,source_id uuid REFERENCES galgo.sources(id),rights_status text NOT NULL,local_asset_path text,caption text);
CREATE TABLE galgo.ingestion_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),git_sha text NOT NULL,files_scanned int NOT NULL DEFAULT 0,inserted int NOT NULL DEFAULT 0,updated int NOT NULL DEFAULT 0,unchanged int NOT NULL DEFAULT 0,superseded int NOT NULL DEFAULT 0,failed int NOT NULL DEFAULT 0,embedding_model text,parser_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE galgo.rag_eval_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question text NOT NULL UNIQUE,expected_documents jsonb NOT NULL DEFAULT '[]',expected_claims jsonb NOT NULL DEFAULT '[]',forbidden_conclusion text,created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
